import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第六十卦 节 水泽节 坎上兑下","description":"周易 - 第六十卦 节 水泽节 坎上兑下","frontmatter":{"title":"第六十卦 节 水泽节 坎上兑下","description":"周易 - 第六十卦 节 水泽节 坎上兑下"},"headers":[],"relativePath":"zh/classics/zhouyi/061.md","filePath":"zh/classics/zhouyi/061.md"}'),l={name:"zh/classics/zhouyi/061.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="节" tabindex="-1">节 <a class="header-anchor" href="#节" aria-label="Permalink to “节”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨。苦节不可贞。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>节，亨，刚柔分，而刚得中。苦节不可贞，其道穷也。说以行险，当位以节，中正以通。天地节而四时成，节以制度，不伤财，不害民。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>泽上有水，节；君子以制数度，议德行。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>不出户庭，无咎。象曰：不出户 庭，知通塞也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>不出门庭，凶。象曰：不出门庭，失时极也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>不节若，则嗟若，无咎。象曰：不节之嗟，又谁咎也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>安节，亨。象曰：安节之亨，承上道也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>甘节，吉；往有尚。象曰：甘节之吉，居位中也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>苦节，贞凶，悔亡。象曰：苦节贞凶，其道穷也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
